app.addEventListener('pointerup', async (event) => { if ((!tradeDrag.active && !tradeDrag.pending) || event.pointerId !== tradeDrag.pointerId) return; if (tradeDrag.pending) { clearTradeDrag(); return; } suppressTradeSummaryClick = true; window.setTimeout(() => { suppressTradeSummaryClick = false; }, 0); const dragged = tradeDrag.id; const slot = tradeDrag.activeDropSlotIndex; const original = [...tradeDrag.originalOrder]; if (dragged && slot !== null) { const ids = original.filter((id) => id !== dragged); ids.splice(Math.max(0, Math.min(slot, ids.length)), 0, dragged); const changed = ids.length !== original.length || ids.some((id, index) => id !== original[index]); if (changed) { const old = daily.report.tradeSections.slice(); daily.update(() => { daily.report.tradeSections = ids.map((id) => old.find((item) => item.id === id)!).filter(Boolean); daily.report.tradeSections.forEach((item, index) => item.sortOrder = index); }); try { await daily.flush(); } catch { daily.report.tradeSections = original.map((id) => old.find((item) => item.id === id)!).filter(Boolean); daily.report.tradeSections.forEach((item, index) => item.sortOrder = index); alert('排序儲存失敗，已恢復原順序。'); } } } clearTradeDrag(); await renderApp(); });
app.addEventListener('pointercancel', () => { if (tradeDrag.active || tradeDrag.pending) { clearTradeDrag(); void renderApp(); } });
window.addEventListener('keydown', (event) => { if (event.key === 'Escape' && (tradeDrag.active || tradeDrag.pending)) { clearTradeDrag(); void renderApp(); } });
app.addEventListener('submit', async (event) => { const form = event.target as HTMLFormElement; if (form.dataset.settingsForm) { event.preventDefault(); try { const name = String(new FormData(form).get('name') ?? ''); const section = settingsState.activeSection; const mode = form.dataset.settingsForm; if (section === 'trade-tasks') { const isTrade = mode === 'trade'; await saveMemory(isTrade ? 'trades' : 'tasks', name, isTrade ? undefined : settingsState.selectedTradeTypeId ?? undefined, isTrade && settingsState.editingId ? settingsState.editingId : !isTrade && mode === 'edit' ? settingsState.editingId ?? undefined : undefined); if (isTrade && mode === 'trade' && !settingsState.editingId) { const created = (await listMemories('trades')).find((item) => item.normalizedName === normalizeSearch(name)); settingsState.selectedTradeTypeId = created?.id ?? null; } } else if (section === 'templates') await saveTemplate(name, mode === 'edit' ? settingsState.editingId ?? undefined : undefined); else await saveMemory(section as 'sites' | 'vendors' | 'locations', name, section === 'vendors' ? settingsState.selectedTradeTypeId ?? undefined : undefined, mode === 'edit' ? settingsState.editingId ?? undefined : undefined); settingsState.adding = false; settingsState.editingId = null; settingsState.dirty = false; await renderApp(); } catch (error) { alert(error instanceof Error ? error.message : '儲存設定失敗。'); } return; } if (form.id === 'trade-picker-form') { event.preventDefault(); const values = new FormData(form); const trade = dailyTrades.find((item) => item.id === String(values.get('tradeId') ?? '')); const vendor = dailyVendors.find((item) => item.id === String(values.get('vendorId') ?? '')); if (!trade || !vendor || vendor.tradeTypeId !== trade.id) { alert('請選擇此工種所屬的廠商。'); return; } const existing = daily.findDuplicate(trade.id, trade.name, vendor.id, vendor.name); daily.addTrade(trade.name, vendor.name, trade.id, vendor.id); if (existing) alert('此工種與廠商已存在。'); tradePickerOpen = false; await daily.flush(); await renderApp(); return; } if (form.id === 'point-form' && water) { event.preventDefault(); await water.handleAction('save-point', String(new FormData(form).get('name') ?? '')); water.renderSettings(); } });
window.addEventListener('beforeunload', (event) => { if (settingsState.dirty && parseRoute(location.hash).page === 'settings') { event.preventDefault(); event.returnValue = ''; } });
window.addEventListener('hashchange', () => { const route = parseRoute(location.hash); if (route.module === 'water-level') void daily.flush(); if (route.module === 'daily' && route.page === 'main') daily.expandedId = null; void renderApp(); });
document.addEventListener('visibilitychange', () => { if (document.hidden) void daily.flush(); });
async function bootstrap(): Promise<void> { daily = new DailyController(await loadDailyDraft()); dailyTrades = await listMemories('trades'); dailyVendors = await listMemories('vendors'); if (!location.hash) location.hash = '#daily'; await renderApp(); if ('serviceWorker' in navigator && import.meta.env.PROD) navigator.serviceWorker.register(`${import.meta.env.BASE_URL}service-worker.js`).catch(() => undefined); }
bootstrap().catch(() => { app.innerHTML = '<main class="app-shell"><h1>無法開啟施工日報</h1><p>請確認瀏覽器允許本機資料儲存。</p></main>'; });
